-- Additional official Cat Parts Store references with explicit marine fitment.
-- These are search references only: no price, stock, or universal serial/Arrangement fitment is asserted.
on conflict (part_number) do update set
  name=excluded.name,
  description=excluded.description,
  engine_models=excluded.engine_models,
  technical_group=excluded.technical_group,
  source_name=excluded.source_name,
  source_url=excluded.source_url,
  source_note=excluded.source_note,
  verification_status='REFERENCE',
  application_type=excluded.application_type,
  application_evidence=excluded.application_evidence,
  application_source_url=excluded.application_source_url,
  updated_at=now();
